package settings

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
)

// Settings holds user preferences persisted on disk.
type Settings struct {
	Theme    string `json:"theme"`
	FontSize int    `json:"fontSize"`
}

func defaults() Settings {
	return Settings{Theme: "light", FontSize: 12}
}

// Load reads settings from path. A missing or empty file yields the
// defaults; values present in the file override them.
func Load(path string) (Settings, error) {
	s := defaults()
	data, err := os.ReadFile(path)
	if errors.Is(err, fs.ErrNotExist) {
		return s, nil
	}
	if err != nil {
		return Settings{}, fmt.Errorf("read settings: %w", err)
	}
	if len(data) > 0 {
		s, err := parse(data)
		if err != nil {
			return Settings{}, fmt.Errorf("parse settings %s: %w", path, err)
		}
		if s.FontSize <= 0 {
			return Settings{}, fmt.Errorf("parse settings %s: invalid font size %d", path, s.FontSize)
		}
	}
	return s, nil
}

func parse(data []byte) (Settings, error) {
	s := defaults()
	if err := json.Unmarshal(data, &s); err != nil {
		return Settings{}, err
	}
	return s, nil
}

