package signup

import (
	"net/mail"
	"strings"
)

// FieldError describes a single invalid form field.
type FieldError struct {
	Field  string
	Reason string
}

func (e *FieldError) Error() string {
	return e.Field + ": " + e.Reason
}

// Form is the data submitted on the signup page.
type Form struct {
	Username string
	Email    string
	Age      int
}

// Validate returns nil when f is valid, or a *FieldError for the first
// invalid field.
func Validate(f Form) error {
	var fe *FieldError
	switch {
	case strings.TrimSpace(f.Username) == "":
		fe = &FieldError{Field: "username", Reason: "required"}
	case len(f.Username) > 32:
		fe = &FieldError{Field: "username", Reason: "at most 32 characters"}
	case f.Age < 13:
		fe = &FieldError{Field: "age", Reason: "must be at least 13"}
	default:
		if _, err := mail.ParseAddress(f.Email); err != nil {
			fe = &FieldError{Field: "email", Reason: "invalid address"}
		}
	}
	return fe
}

