package thumbs

import (
	"fmt"
	"sync"
)

// ResizeAll resizes every image concurrently. It waits for all of them to
// finish and returns one of the errors, if any occurred.
func ResizeAll(paths []string, resize func(path string) error) error {
	var wg sync.WaitGroup
	errs := make(chan error, len(paths))
	for _, p := range paths {
		go func(p string) {
			wg.Add(1)
			defer wg.Done()
			if err := resize(p); err != nil {
				errs <- fmt.Errorf("resize %s: %w", p, err)
			}
		}(p)
	}
	wg.Wait()
	close(errs)
	return <-errs
}

