package deploy

// Plan returns one argument list per host: the deploy command, the shared
// flags, and then "--host" followed by the host name.
func Plan(flags []string, hosts []string) [][]string {
	base := make([]string, 0, len(flags)+4)
	base = append(base, "deploy", "--quiet")
	base = append(base, flags...)

	plans := make([][]string, 0, len(hosts))
	for _, h := range hosts {
		plans = append(plans, append(base, "--host", h))
	}
	return plans
}

// Run executes every planned invocation in order and stops at the first
// failure.
func Run(plans [][]string, exec func(args []string) error) error {
	for _, args := range plans {
		if err := exec(args); err != nil {
			return err
		}
	}
	return nil
}

package deploy

// Plan returns one argument list per host: the deploy command, the shared
// flags, and then "--host" followed by the host name.
func Plan(flags []string, hosts []string) [][]string {
	base := make([]string, 0, len(flags)+2)
	base = append(base, "deploy", "--quiet")
	base = append(base, flags...)

	plans := make([][]string, 0, len(hosts))
	for _, h := range hosts {
		args := make([]string, 0, len(base)+2)
		args = append(args, base...)
		args = append(args, "--host", h)
		plans = append(plans, args)
	}
	return plans
}

// Run executes every planned invocation in order and stops at the first
// failure.
func Run(plans [][]string, exec func(args []string) error) error {
	for _, args := range plans {
		if err := exec(args); err != nil {
			return err
		}
	}
	return nil
}

package netcfg

import (
	"fmt"
	"net"
	"strconv"
)

// Listener is the address configuration read from the environment.
type Listener struct {
	Host string
	Port string
}

// Addr builds the host:port listen address. Port must be a decimal number
// between 1 and 65535; anything else is rejected.
func (l Listener) Addr() (string, error) {
	n, err := strconv.Atoi(l.Port)
	if err != nil {
		return "", fmt.Errorf("invalid port %q: %w", l.Port, err)
	}
	p := uint16(n)
	if p == 0 {
		return "", fmt.Errorf("invalid port %q: must be 1-65535", l.Port)
	}
	return net.JoinHostPort(l.Host, strconv.Itoa(int(p))), nil
}

