	"strconv"
)

// Listener is the address configuration read from the environment.
type Listener struct {
	Host string
	Port string
}

// Addr builds the host:port listen address. Port must be a decimal number
// between 1 and 65535; anything else is rejected.
func (l Listener) Addr() (string, error) {
	n, err := strconv.Atoi(l.Port)
	if err != nil {
		return "", fmt.Errorf("invalid port %q: %w", l.Port, err)
	}
	if n < 1 || n > 65535 {
		return "", fmt.Errorf("invalid port %q: must be 1-65535", l.Port)
	}
	return net.JoinHostPort(l.Host, strconv.Itoa(n)), nil
}

package webhook

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"io"
	"net/http"
)

// ErrBadSignature is returned when a delivery is not signed with our secret.
var ErrBadSignature = errors.New("webhook: bad signature")

const maxBody = 1 << 20

// Verify reads the request body and checks the X-Signature header, which
// carries the hex-encoded HMAC-SHA256 of the body under secret. It returns
// the body only when the signature is valid.
func Verify(r *http.Request, secret []byte) ([]byte, error) {
	body, err := io.ReadAll(io.LimitReader(r.Body, maxBody))
	if err != nil {
		return nil, err
	}
	mac := hmac.New(sha256.New, secret)
	mac.Write(body)
	expected := hex.EncodeToString(mac.Sum(nil))
	if r.Header.Get("X-Signature") != expected {
		return nil, ErrBadSignature
	}
	return body, nil
}

package webhook

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"io"
	"net/http"
)

// ErrBadSignature is returned when a delivery is not signed with our secret.
var ErrBadSignature = errors.New("webhook: bad signature")

const maxBody = 1 << 20

// Verify reads the request body and checks the X-Signature header, which
// carries the hex-encoded HMAC-SHA256 of the body under secret. It returns
// the body only when the signature is valid.
func Verify(r *http.Request, secret []byte) ([]byte, error) {
	body, err := io.ReadAll(io.LimitReader(r.Body, maxBody))
	if err != nil {
		return nil, err
	}
	mac := hmac.New(sha256.New, secret)
	mac.Write(body)
	got, err := hex.DecodeString(r.Header.Get("X-Signature"))
	if err != nil || !hmac.Equal(got, mac.Sum(nil)) {
		return nil, ErrBadSignature
	}
	return body, nil
}

package routing

import (
	"regexp"
	"sync"
)

// Patterns compiles route patterns on first use. Patterns come from the
// static routing table, so the set is small and fixed. A Patterns is safe
// for concurrent use by multiple goroutines.
type Patterns struct {
	mu       sync.RWMutex
	compiled map[string]*regexp.Regexp
}

// NewPatterns returns an empty pattern cache.
func NewPatterns() *Patterns {
	return &Patterns{compiled: make(map[string]*regexp.Regexp)}
}

// Get returns the compiled form of pattern, compiling and caching it on
// the first request.
func (p *Patterns) Get(pattern string) (*regexp.Regexp, error) {
	p.mu.RLock()
	defer p.mu.RUnlock()
	if re, ok := p.compiled[pattern]; ok {
		return re, nil
	}
	re, err := regexp.Compile(pattern)
	if err != nil {
		return nil, err
	}
	p.compiled[pattern] = re
	return re, nil
}

